-- PostgreSQL-compatible relational schema. Event history is append-only.
CREATE TABLE facilities (facility_id varchar(16) PRIMARY KEY, name text NOT NULL, timezone text NOT NULL, effective_from timestamptz NOT NULL, active boolean NOT NULL);
CREATE TABLE docks (dock_id varchar(32) PRIMARY KEY, facility_id varchar(16) NOT NULL REFERENCES facilities, dock_type text NOT NULL CHECK (dock_type IN ('STANDARD','REFRIGERATED','HAZMAT')), length_m numeric NOT NULL, capacity_units int NOT NULL CHECK(capacity_units>0), active boolean NOT NULL);
CREATE TABLE yard_slots (yard_slot_id varchar(40) PRIMARY KEY, facility_id varchar(16) NOT NULL REFERENCES facilities, slot_type text NOT NULL, capacity_units int NOT NULL CHECK(capacity_units>0), active boolean NOT NULL);
CREATE TABLE carriers (carrier_id varchar(16) PRIMARY KEY, name text NOT NULL, scac varchar(8) UNIQUE NOT NULL, active boolean NOT NULL);
CREATE TABLE vehicles (vehicle_id varchar(16) PRIMARY KEY, carrier_id varchar(16) NOT NULL REFERENCES carriers, vehicle_type text NOT NULL, length_m numeric NOT NULL, capability text NOT NULL, active boolean NOT NULL);
CREATE TABLE labor_shifts (labor_shift_id varchar(40) PRIMARY KEY, facility_id varchar(16) NOT NULL REFERENCES facilities, shift_code text NOT NULL, start_ts timestamptz NOT NULL, end_ts timestamptz NOT NULL CHECK(end_ts>start_ts), workers int NOT NULL CHECK(workers>0), skills text NOT NULL, status text NOT NULL);
CREATE TABLE capacity_calendars (calendar_id varchar(48) PRIMARY KEY, facility_id varchar(16) NOT NULL REFERENCES facilities, labor_shift_id varchar(40) NOT NULL REFERENCES labor_shifts, calendar_date date NOT NULL, dock_capacity int NOT NULL, yard_capacity int NOT NULL, labor_capacity int NOT NULL, effective_from timestamptz NOT NULL, UNIQUE(facility_id,calendar_date,labor_shift_id));
CREATE TABLE shipments (shipment_id varchar(24) PRIMARY KEY, carrier_id varchar(16) NOT NULL REFERENCES carriers, direction text NOT NULL CHECK(direction IN ('INBOUND','OUTBOUND')), load_type text NOT NULL CHECK(load_type IN ('STANDARD','REFRIGERATED','HAZMAT')), weight_kg numeric NOT NULL, pallet_count int NOT NULL, status text NOT NULL);
CREATE TABLE handling_requirements (handling_requirement_id varchar(24) PRIMARY KEY, shipment_id varchar(24) NOT NULL UNIQUE REFERENCES shipments, requirement_type text NOT NULL, requires_reefer boolean NOT NULL, requires_hazmat_cert boolean NOT NULL, service_minutes int NOT NULL);
CREATE TABLE appointments (appointment_id varchar(24) PRIMARY KEY, facility_id varchar(16) NOT NULL REFERENCES facilities, vehicle_id varchar(16) NOT NULL REFERENCES vehicles, appointment_type text NOT NULL CHECK(appointment_type IN ('INBOUND','OUTBOUND')), requested_start_ts timestamptz NOT NULL, scheduled_start_ts timestamptz NULL, scheduled_end_ts timestamptz NULL, status text NOT NULL CHECK(status IN ('REQUESTED','CONFIRMED','WAITLISTED','CHECKED_IN','IN_SERVICE','COMPLETED','NO_SHOW','CANCELLED')), allocation_reason text NOT NULL, service_minutes int NOT NULL, created_ts timestamptz NOT NULL);
CREATE TABLE appointment_shipments (appointment_id varchar(24) REFERENCES appointments, shipment_id varchar(24) REFERENCES shipments, sequence_no int NOT NULL, PRIMARY KEY(appointment_id,shipment_id));
CREATE TABLE dock_reservations (dock_reservation_id varchar(32) PRIMARY KEY, appointment_id varchar(24) UNIQUE NOT NULL REFERENCES appointments, dock_id varchar(32) NOT NULL REFERENCES docks, start_ts timestamptz NOT NULL, end_ts timestamptz NOT NULL CHECK(end_ts>start_ts), status text NOT NULL);
CREATE TABLE yard_reservations (yard_reservation_id varchar(32) PRIMARY KEY, appointment_id varchar(24) UNIQUE NOT NULL REFERENCES appointments, yard_slot_id varchar(40) NOT NULL REFERENCES yard_slots, start_ts timestamptz NOT NULL, end_ts timestamptz NOT NULL CHECK(end_ts>start_ts), status text NOT NULL);
CREATE TABLE labor_allocations (labor_allocation_id varchar(32) PRIMARY KEY, appointment_id varchar(24) UNIQUE NOT NULL REFERENCES appointments, labor_shift_id varchar(40) NOT NULL REFERENCES labor_shifts, workers_required int NOT NULL, skill text NOT NULL, status text NOT NULL);
CREATE TABLE checkin_events (checkin_event_id varchar(40) PRIMARY KEY, appointment_id varchar(24) NOT NULL REFERENCES appointments, event_type text NOT NULL CHECK(event_type IN ('CHECKED_IN','NO_SHOW')), event_ts timestamptz NOT NULL, arrival_class text NOT NULL);
CREATE TABLE operational_events (event_id varchar(24) PRIMARY KEY, appointment_id varchar(24) NOT NULL REFERENCES appointments, event_type text NOT NULL, event_ts timestamptz NOT NULL, sequence_no int NOT NULL, source text NOT NULL, UNIQUE(appointment_id,sequence_no));
CREATE TABLE exceptions (exception_id varchar(16) PRIMARY KEY, appointment_id varchar(24) NULL REFERENCES appointments, issue_type text NOT NULL, cause_code text NOT NULL, severity text NOT NULL, source text NOT NULL, status text NOT NULL DEFAULT 'OPEN');
CREATE TABLE derived_metrics (appointment_id varchar(24) PRIMARY KEY REFERENCES appointments, scheduled_service_minutes int NOT NULL, actual_service_minutes int NOT NULL, waiting_minutes int NOT NULL, turnaround_minutes int NOT NULL, appointment_status text NOT NULL);
CREATE TABLE resource_utilization_metrics (facility_id varchar(16) PRIMARY KEY REFERENCES facilities, period_start_ts timestamptz NOT NULL, period_end_ts timestamptz NOT NULL, dock_utilization numeric NOT NULL, yard_utilization numeric NOT NULL, labor_utilization numeric NOT NULL, no_show_count int NOT NULL, exception_count int NOT NULL);
CREATE INDEX ix_appointments_facility_start ON appointments(facility_id,scheduled_start_ts); CREATE INDEX ix_reservations_dock_time ON dock_reservations(dock_id,start_ts,end_ts); CREATE INDEX ix_events_appointment_time ON operational_events(appointment_id,event_ts); CREATE INDEX ix_exceptions_type_status ON exceptions(issue_type,status); CREATE INDEX ix_vehicles_carrier ON vehicles(carrier_id);
